// Generated by npm run build:extension. Edit adapter source modules instead.
(()=>{
'use strict';
// Original adapter code. No SillyTavern implementation is bundled here.
const WIRE_PREFIX='BUILD_ST_CONTEXT_V1\n';
const MODEL_PREFIX='build-st/';
function isBuildConnection(data){
 return String(data.model||'').startsWith(MODEL_PREFIX)&&(data.chat_completion_source==='custom'||(data.chat_completion_source==='openai'&&typeof data.reverse_proxy==='string'&&!!data.reverse_proxy.trim()));
}
const MAX_SEGMENTS=20000;
const background=new Set(['worldInfoBefore','worldInfoAfter','charDescription','charPersonality','scenario','personaDescription','dialogueExamples','summary','authorsNote','vectorsMemory','vectorsDataBank','smartContext']);
const controls=new Set(['main','nsfw','jailbreak','enhanceDefinitions','groupNudge','continueNudge','impersonate','quietPrompt','bias','newMainChat','newChat','emptyUserMessageReplacement']);
const fail=code=>{throw Object.assign(new Error(code),{code});};
function presetSource(id,settings){
 if(background.has(id))return false;
 if(controls.has(id))return true;
 return !!settings?.prompts?.some(p=>p.identifier===id&&p.marker!==true&&!background.has(id));
}
// Temporary boundaries survive ST's in-chat prompt grouping. They are added to
// prepared copies only, never to saved presets or chat messages.
function createTagger(nonce){
 if(!/^[a-f0-9]{24}$/.test(nonce))fail('invalid_nonce');
 let sequence=0,fault=null;const entries=new Map(),bySource=new Map();
 const prefix=`[[BST:${nonce}:`;
 const expression=new RegExp(`\\[\\[BST:${nonce}:(\\d+):(BEGIN|END)\\]\\]`,'g');
 function split(text,fallback){
  const output=[];let offset=0,active=null,found=0;
  for(const match of text.matchAll(expression)){
   const meta=entries.get(match[1]);if(!meta)fail('unknown_boundary');
   if(match.index>offset)output.push({...active?.meta||fallback,text:text.slice(offset,match.index)});
   if(match[2]==='BEGIN'){if(active)fail('nested_boundary');active={id:match[1],meta};}
   else {if(active?.id!==match[1])fail('broken_boundary');active=null;}
   offset=match.index+match[0].length;found++;
  }
  if(active)fail('broken_boundary');
  if(offset<text.length)output.push({...fallback,text:text.slice(offset)});
  if(!found&&text.includes(prefix))fail('broken_boundary');
  return output.length?output:[{...fallback,text:''}];
 }
 function strip(text){return typeof text==='string'?split(text,{}).map(x=>x.text).join(''):text;}
 function mark(text,meta){
  if(!text)return text;
  const key=JSON.stringify(meta);let id=bySource.get(key);
  if(!id){
   if(entries.size>=MAX_SEGMENTS){fault='boundary_capacity';fail(fault);}
   id=String(++sequence);entries.set(id,meta);bySource.set(key,id);
  }
  return `${prefix}${id}:BEGIN]]${text}${prefix}${id}:END]]`;
 }
 return {split,strip,mark,prefix,get fault(){return fault;}};
}

function hookPromptManager(manager,tagger,active){
 const original=manager.preparePrompt;
 if(typeof original!=='function')fail('prompt_api_missing');
 function prepared(prompt,originalText=null){
  if(!active())return original.call(this,prompt,originalText);
  const id=prompt?.identifier||'';
  const history=/^chatHistory-\d+$/.test(id);
  // Re-preparation of a history message must retain its inner source boundaries.
  const source=history?prompt:{...prompt,content:tagger.strip(prompt?.content)};
  const result=original.call(this,source,tagger.strip(originalText));
  if(result?.then)fail('prompt_api_async');
  if(history||typeof result?.content!=='string'||!result.content)return result;
  const placement=presetSource(id,this.serviceSettings)?'inline':'file';
  return Object.assign(Object.create(Object.getPrototypeOf(result)),result,{content:tagger.mark(result.content,{source:id||'context',placement})});
 }
 manager.preparePrompt=prepared;
 return ()=>{if(manager.preparePrompt===prepared)manager.preparePrompt=original;};
}

function textMessage(m){
 if(!m||!['system','developer','user','assistant'].includes(m.role)||typeof m.content!=='string'||m.tool_calls||m.function_call||m.reasoning||m.signature)fail('text_only');
 if(m.name!==undefined&&(typeof m.name!=='string'||m.name.length>128))fail('invalid_name');
 return {role:m.role,content:m.content,...(m.name?{name:m.name}:{})};
}
// Read the enabled presets where ST actually prepares them, then extract their
// final expanded copies at send time. All other final text is background. No
// comparison with Prompt Manager's mutable inspection tree is needed.
function readPresetSegments(chat,tagger,{latestUserText}={}){
 if(tagger.fault)fail(tagger.fault);
 if(!Array.isArray(chat)||!chat.length)fail('text_only');
 const pieces=[];let prepared=false,current=-1;
 for(let i=0;i<chat.length;i++){
  const sent=textMessage(chat[i]);
  if(sent.content.includes(tagger.prefix))prepared=true;
  const split=tagger.split(sent.content,{source:'conversation-context',placement:'file'});
  // An exact unmarked user message can remain in the composer. A user-role
  // preset or World Info fragment must never be promoted as the current turn.
  if(sent.role==='user'&&sent.content===latestUserText&&!sent.content.includes(tagger.prefix))current=i;
  split.forEach((piece,part)=>pieces.push({message:i,part,role:sent.role,...(sent.name?{name:sent.name}:{}),...piece}));
 }
 if(!prepared)fail('preset_not_ready');
 for(const piece of pieces)if(piece.message===current){piece.placement='inline';piece.source='currentUser';}
 if(pieces.length>MAX_SEGMENTS)fail('too_many_segments');
 return pieces;
}
function encodeEnvelope(segments,generationType='normal',inlineTokens=null){
 return {role:'user',content:WIRE_PREFIX+JSON.stringify({version:1,generationType:generationType||'normal',segments,inlineTokens})};
}
function errorEnvelope(code){return {role:'user',content:WIRE_PREFIX+JSON.stringify({version:1,error:code})};}
const excludedSampling=['temperature','top_p','top_k','top_a','min_p','presence_penalty','frequency_penalty','repetition_penalty','stop','seed','logprobs','top_logprobs','logit_bias','reasoning_effort','user','verbosity'];
function prepareOutgoing(data,prepared,{inlineTokens=null,tokenBudget=45000}={}){
 if(!isBuildConnection(data))return null;
 if(data.tools?.length||data.functions?.length||data.json_schema||data.request_images||data.n>1)fail('text_only');
 if(data.chat_completion_source==='custom'&&(String(data.custom_include_body||'').trim()||String(data.custom_exclude_body||'').trim()))fail('custom_body_conflict');
 if(!prepared)fail('preset_not_ready');
 if(!Number.isFinite(inlineTokens)||inlineTokens<0)fail('token_count_unavailable');
 if(inlineTokens>tokenBudget)fail('inline_budget_exceeded');
 return encodeEnvelope(prepared.segments,prepared.generationType||data.type,Math.ceil(inlineTokens));
}
function applyOutgoing(data,envelope){
 // Custom-body JSON is also valid YAML, and ST applies it after constructing
 // the OpenAI body. No server plugin or modification of ST core is required.
 data.messages=[envelope];
 if(data.chat_completion_source==='custom'){
  data.custom_include_body=JSON.stringify({messages:[envelope]});
  data.custom_exclude_body=JSON.stringify(excludedSampling);
  data.custom_prompt_post_processing='';
 }else{
  // ST's OpenAI reverse-proxy path forwards messages directly and never
  // applies custom-body overrides. Preserve its route and credentials.
  for(const field of excludedSampling)delete data[field];
 }
}


function installSillyTavern({getContext,openAI,owner='legacy'}){
const key='build_standalone_adapter';
const singleton=Symbol.for('build-standalone.sillytavern.v1');
if(globalThis[singleton])return globalThis[singleton];
const {oai_settings,setOpenAIMessages}=openAI;
const tagger=createTagger(Array.from(crypto.getRandomValues(new Uint8Array(12)),x=>x.toString(16).padStart(2,'0')).join(''));
let hooked=null,statusElement,generationType='normal';
const context=()=>getContext();
const settings=()=>context().extensionSettings[key]??={enabled:true};
const active=()=>settings().enabled&&isBuildConnection({chat_completion_source:oai_settings.chat_completion_source,model:oai_settings.chat_completion_source==='openai'?oai_settings.openai_model:oai_settings.custom_model,reverse_proxy:oai_settings.reverse_proxy});
const messages={
 preset_not_ready:'尚未读取到本次酒馆预设。请刷新酒馆后发送聊天；“测试连接”请使用普通 gemini 模型。',
 preset_read_failed:'读取本次预设失败，请查看扩展控制台中的错误代码。',
 text_only:'目前仅支持纯文本和单次生成；请关闭工具、图片、JSON schema 与多候选回复。',
 custom_body_conflict:'请清空此连接的“自定义请求正文”和“排除正文参数”；扩展需要按请求设置它们。',
 inline_budget_exceeded:'输入框内容估算超过 45000 token。预设没有被截断或移入文件，请缩短预设。',
 token_count_unavailable:'酒馆无法完成 token 估算，已阻止请求。',
 adapter_disabled:'请启用浏览器连接器中的酒馆预设分流。',
 prompt_api_missing:'当前酒馆缺少所需 Prompt Manager 接口。',
 broken_boundary:'内容边界被修改，已阻止请求。',
 unknown_boundary:'内容来源标记已失效，请重新生成。',
};
function status(text,bad=false){if(statusElement){statusElement.textContent=text;statusElement.dataset.error=String(bad);}}
function ensureHook(){
 const promptManager=openAI.promptManager;
 if(promptManager&&hooked!==promptManager){hookPromptManager(promptManager,tagger,active);hooked=promptManager;}
}
function start(type,_options,dryRun){ensureHook();if(!dryRun)generationType=['normal','regenerate','swipe','continue','quiet','impersonate'].includes(type)?type:'normal';}
async function send(data){
 if(!isBuildConnection(data)){
  // A user can switch connections during prompt preparation. Remove our own
  // transient boundaries if that happens, without changing ordinary requests.
  for(const message of data.messages||[])if(typeof message.content==='string'&&message.content.includes(tagger.prefix))message.content=tagger.strip(message.content);
  return;
 }
 let envelope;
 try{
  if(!settings().enabled)throw {code:'adapter_disabled'};
  const latest=setOpenAIMessages(context().chat||[]).find(m=>m.role==='user')?.content;
  const prepared={segments:readPresetSegments(data.messages,tagger,{latestUserText:latest}),generationType};
  const inline=prepared.segments?.filter(s=>s.placement==='inline').map(s=>s.text).join('\n')||'';
  // ST's tokenizer is an estimate, not Google's authoritative token counter.
  const tokens=await context().getTokenCountAsync(inline);
  envelope=prepareOutgoing(data,prepared,{inlineTokens:tokens,tokenBudget:45000});
  const files=prepared.segments.filter(s=>s.placement==='file'),presets=prepared.segments.filter(s=>s.placement==='inline');
  status(`已直接读取启用预设：输入框 ${presets.length} 段 / ${inline.length} 字符（估算 ${tokens} token）；历史和背景文件 ${files.length} 段 / ${files.reduce((n,s)=>n+s.text.length,0)} 字符。`);
 }catch(e){
  const code=messages[e.code]?e.code:'preset_read_failed';envelope=errorEnvelope(code);
  console.info('[Build preset diagnostic]',JSON.stringify({code:e.code||'preset_read_failed'}));
  const message=messages[code];status(message,true);globalThis.toastr?.error(message,'Build 酒馆适配');
 }
 // ST's event emitter catches thrown errors, so a rejection envelope is sent
 // instead of relying on throw to stop generation. The gateway rejects it
 // before selecting an account. Old gateways reject the build-st/ namespace.
 applyOutgoing(data,envelope);
}
function mount(){
 ensureHook();
 const host=document.querySelector('#extensions_settings2')||document.querySelector('#extensions_settings');
 if(!host||document.getElementById('build-standalone-adapter-settings'))return;
 const panel=document.createElement('div');panel.dataset.buildAdapterOwner=owner;panel.id='build-standalone-adapter-settings';panel.className='inline-drawer';
 panel.innerHTML='<div class="inline-drawer-toggle inline-drawer-header"><b>Build 独立版 · 酒馆分流</b><div class="inline-drawer-icon fa-solid fa-circle-chevron-down down"></div></div><div class="inline-drawer-content"><label class="checkbox_label"><input type="checkbox" data-enable>直接读取当前启用预设</label><p>版本 0.5.0（'+(owner==='browser'?'浏览器连接器内置':'兼容酒馆扩展')+'）。支持自定义 OpenAI 或 OpenAI＋反向代理连接中的 <code>build-st/</code> 模型。预设进输入框；历史、世界书和角色资料进项目文件。普通连接不变。</p><p>允许合并系统消息和后期提示词修改；使用自定义连接时需清空自定义正文与排除正文参数。输入框估算上限 45000 token；Build 不支持的温度、Top-P、stop 等采样参数不会转发。思考强度仍由模型后缀决定。</p><p data-status role="status">等待酒馆专用模型请求；此扩展不会自行调用模型。</p></div>';
 host.append(panel);statusElement=panel.querySelector('[data-status]');
 const enabled=panel.querySelector('[data-enable]');enabled.checked=settings().enabled;
 enabled.addEventListener('change',()=>{settings().enabled=enabled.checked;context().saveSettingsDebounced();status('设置已保存。');});
}
const ctx=context();
const instance={owner,version:'0.5.0'};
globalThis[singleton]=instance;
ctx.eventSource.on(ctx.eventTypes.GENERATION_STARTED,start);
ctx.eventSource.makeLast(ctx.eventTypes.CHAT_COMPLETION_SETTINGS_READY,send);
ctx.eventSource.on(ctx.eventTypes.APP_READY,mount);
mount();

return instance;
}

// Runs in the page's MAIN world. No extension credentials or Chrome APIs here.

async function connectSillyTavernPage({root=globalThis,doc=document,loadOpenAI=()=>import(new URL('/scripts/openai.js',location.origin).href)}={}){
 if(!root.SillyTavern?.getContext||!doc.querySelector('#send_textarea')||!doc.querySelector('#chat')||doc.querySelector('#preloader, #loader'))return 'waiting';
 const existing=root[Symbol.for('build-standalone.sillytavern.v1')];
 if(existing)return existing.owner==='browser'?'connected':'legacy';
 // Old 0.3 adapters have private listeners that cannot be safely removed.
 // Wait until ST finishes loading extensions, then leave them as sole owner.
 const oldPanel=doc.getElementById('build-standalone-adapter-settings');
 const oldScript=Array.from(doc.scripts||[]).some(s=>{try{return new URL(s.src,location.href).pathname.endsWith('/build-standalone-adapter/index.js');}catch{return false;}});
 if(oldPanel||oldScript){
  if(oldPanel&&!oldPanel.querySelector('[data-build-migration]')){
   const note=doc.createElement('p');note.dataset.buildMigration='true';
   note.textContent='浏览器连接器已内置酒馆分流。当前仍由旧酒馆扩展处理；请在管理扩展中禁用旧 Build 适配扩展并刷新，由连接器自动接管。';oldPanel.append(note);
  }
  return 'legacy';
 }
 const openAI=await loadOpenAI();
 installSillyTavern({getContext:root.SillyTavern.getContext,openAI,owner:'browser'});
 return 'connected';
}

function watchSillyTavernPage(){
 if(window.top!==window)return;
 const marker=Symbol.for('build-standalone.sillytavern.loader');
 if(globalThis[marker])return;
 globalThis[marker]=true;
 let timer,busy=false,done=false;
 const poll=async()=>{
  if(busy||done)return;busy=true;
  try{const state=await connectSillyTavernPage();if(state!=='waiting'){done=true;clearInterval(timer);document.documentElement.dataset.buildSillyTavern=state;}}
  catch{done=true;clearInterval(timer);document.documentElement.dataset.buildSillyTavern='error';console.warn('[Build connector] 酒馆分流加载失败，请刷新页面并确认酒馆版本支持 Prompt Manager。');}
  finally{busy=false;}
 };
 timer=setInterval(poll,500);void poll();
 window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});
}

watchSillyTavernPage();
})();
